css.P1:
/* banner canvas (fixed brand colors, never theme). Ground: the matte paper texture from
   Lucas's Figma pass (a warm light salmon with a soft, uneven lift and fine grain), one
   image for every size, cover-fitted. #F6E6DE stays as the fallback colour. */
.kn{position:relative;overflow:hidden;background:#F6E6DE center/cover no-repeat;
  color:#131540;font-family:var(--font-brand);font-weight:300;-webkit-font-smoothing:antialiased;flex:none}
.kn > *{position:absolute;margin:0}
.kn-logo{display:block;height:auto;aspect-ratio:521/116;color:#EC5370;fill:currentColor}
/* copy column: explicit line breaks per size (from Figma), nothing wraps on its own.
   Weights matched by eye to the Figma render: Figma's SemiBold headline = the hub's 500,
   Figma's Medium CTA = the hub's 400 (the hub's 500 draws heavier than Figma's Medium) */
.kn-text{display:flex;flex-direction:column;align-items:flex-start;white-space:nowrap}
.kn-h{margin:0;font-weight:500;color:#131540}
.kn-s{margin:0;font-weight:400;color:#131540}
.kn-cta{display:inline-flex;align-items:center;justify-content:center;text-align:center;border-radius:999px;background:#ED5370;color:#FFFFFF;font-weight:400;white-space:nowrap}
/* each product: Figma's box; the image sits inside a clip box (Figma's crop, rotation) and
   the shadow is a drop-shadow so it follows the cutout, not the box */
.kn-item{position:absolute;display:block}
.kn-clip{position:absolute;overflow:hidden}
.kn-clip img{position:absolute;display:block;max-width:none}
.kn-hide{visibility:hidden}

.kn{background-image:none}

css.P2:
/* banner canvas (fixed brand colors, never theme). Round 4: matches Lucas's Figma frames. */
.k20{position:relative;overflow:hidden;background:#131540;color:#FFFFFF;font-family:var(--font-brand);font-weight:300;-webkit-font-smoothing:antialiased;flex:none}
.k20 > *{position:absolute;margin:0}
.k20-logo{display:block;height:auto;aspect-ratio:521/116;fill:currentColor}
/* the headline sits low on the photo as highlight bars, one bar per line: setup in Dark Blue on
   Cream, punchline in Pink on Dark Blue. Bars hug their line and stack with no gap. */
.k20-h{display:flex;flex-direction:column;align-items:flex-start;font-weight:700;line-height:1;letter-spacing:-.025em;white-space:nowrap}
.k20-h.k20-center{align-items:center;text-align:center}
.k20-h > span{display:block;flex:none}
.k20-h .t1{background:#EAD0B6;color:#131540}
.k20-h .t2{background:#131540;color:#ED5370}
.k20-cta{display:flex;align-items:center;justify-content:center;box-sizing:border-box;text-align:center;border-radius:999px;background:#ED5370;color:#FFFFFF;font-weight:500;letter-spacing:-.005em;white-space:nowrap}
.k20-cta > span{display:block}
.k20-cta > .trim{text-box:trim-both cap alphabetic}
.k20-disc{transform:translate(-50%,-50%);font-weight:500;color:#FFFFFF;white-space:nowrap;text-align:center}

/* the photo, full-bleed (or a block at the right end of the leaderboards), with Figma's scrims */
.k20-pic{overflow:hidden;background:#282B60}
.k20-pic img{position:absolute;display:block;max-width:none}
.k20-fade{pointer-events:none}

css.P3:
/* banner canvas (fixed brand colors, never theme). Values measured from Figma 547:1720 */
.k21{--k21-bg:#131540;--k21-t1:#FFFFFF;--k21-t2:#ED5370;--k21-ta:#AFB3CC;--k21-sub:#AFB3CC;position:relative;overflow:hidden;background:var(--k21-bg);color:var(--k21-t1);font-family:var(--font-brand);font-weight:400;-webkit-font-smoothing:antialiased;flex:none}
/* V2: Cream ground, Blue first sentence, Dark Blue accent words and subhead */
.k21.k21-v2{--k21-bg:#EAD0B6;--k21-t1:#364488;--k21-t2:#ED5370;--k21-ta:#131540;--k21-sub:#131540}
.k21 > *{position:absolute;margin:0}
.k21-logo{display:block;height:auto;aspect-ratio:521/116;color:#ED5370;fill:currentColor}
.k21-h{font-weight:700;letter-spacing:-.03em;white-space:nowrap}
.k21-h>span,.k21-s2>span,.k21-cta>span{display:block;white-space:nowrap}
.k21-h .t1{color:var(--k21-t1)}
.k21-h .t2{color:var(--k21-t2)}
.k21-h .ta{color:var(--k21-ta)}
.k21-s2{font-weight:400;color:var(--k21-sub);white-space:nowrap}
.k21-cta{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;box-sizing:border-box;border-radius:999px;background:#ED5370;color:#FFFFFF;font-weight:500;white-space:nowrap}
.k21 .k21-c{text-align:center;transform:translateX(-50%)}
.k21-h.k21-c>span,.k21-s2.k21-c>span{margin-inline:auto}

css.P4:
/* ============ Banners channel: KAT26022 Trusted ============ */
.k22-frame{position:relative;overflow:hidden}
.k22-frame > .k22{transform-origin:0 0}

/* banner canvas (fixed brand colors, never theme). Pass 8: every element is placed
   absolutely at its Figma frame-relative position by k22.js (Figma 547:1720). */
.k22{position:relative;overflow:hidden;background:#131540;color:#FFFFFF;font-family:var(--font-brand);font-weight:300;-webkit-font-smoothing:antialiased;flex:none}
.k22 > *{position:absolute;margin:0;box-sizing:border-box}
.k22-logo{display:block;height:auto;aspect-ratio:521/116;color:#EC5370;fill:currentColor}
/* headline: Figma sets it in Aktiv Grotesk SemiBold; the hub embeds 300/400/500/700,
   so it renders in Medium (500), this brand's own headline weight */
.k22-h{font-weight:500;color:#FFFFFF;white-space:nowrap;text-align:center}
.k22-s2{font-weight:400;color:#AFB3CC;white-space:nowrap;text-align:center}
.k22-h>span,.k22-s2>span{display:block}
.k22-left{text-align:left}
/* a large circle behind the badge (Figma "Background", #282B60) */
.k22-arc{border-radius:50%;background:#282B60}
.k22-cta{display:flex;flex-direction:column;align-items:center;justify-content:center;border-radius:999px;background:#ED5370;color:#FFFFFF;font-weight:500;white-space:nowrap;text-align:center}
.k22-cta>span{display:block}

/* the one trust element: white card, flat cream offset plate (never a blurred shadow),
   Trustpilot wordmark + stars only, no quote, no invented TrustScore */
.k22-tp{display:flex;flex-direction:column;align-items:center;justify-content:center;background:#FFFFFF}
.k22-tp-word{display:block;font-weight:700;line-height:normal;color:#191919;letter-spacing:-.01em;white-space:nowrap}
.k22-tp-stars{display:block;color:#00B67A;white-space:nowrap}

/* decorative texture: straight star-only cards (no rotation), each with one soft
   drop shadow and the frame's single light blur, set inline from Figma */
.k22-deco{display:flex;align-items:center;justify-content:center;background:#FFFFFF}
.k22-deco-stars{display:block;color:#00B67A;white-space:nowrap}

/* Option B: the shopper photo, cropped inside its rounded box exactly as in Figma
   (library: laptop-woman-window-desk-06). Light Blue under it while it decodes. */
.k22-pic{overflow:hidden;background:#9EB5C0}
.k22-pic>img{position:absolute;display:block;max-width:none}
